//! Emit a plain C23 symbol table (name → RVA) for runtime resolution.
//!
//! This is the ground-truth bridge between the IR and a runtime consumer
//! (venir): sorted array + binary search, keyed on the version-stable
//! mangled name, RVA computed against the PE image base. Version-anchored
//! by the PDB GUID embedded in the header.

use crate::model::{Database, Kind};
use anyhow::{Context, Result};
use std::fmt::Write as _;
use std::path::Path;

pub fn emit_syms(db: &Database, name: &str, out_dir: &Path, image_base: u64) -> Result<()> {
    std::fs::create_dir_all(out_dir).with_context(|| format!("creating {}", out_dir.display()))?;

    let ident = c_ident(name);
    let upper = ident.to_ascii_uppercase();
    let h_path = out_dir.join(format!("{ident}_syms.h"));
    let c_path = out_dir.join(format!("{ident}_syms.c"));

    let guid = db.binary.pdb_guid.as_deref().unwrap_or("unknown");
    let age = db.binary.pdb_age.unwrap_or(0);
    let timestamp = db
        .binary
        .timestamp
        .as_deref()
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or(0);

    // Ground-truth table: skip CRT/STL boilerplate, require a real address.
    let mut rows: Vec<(String, String, u32, u32, u8, u8)> = db
        .symbols
        .iter()
        .filter(|s| !s.library && s.vaddr != 0 && s.vaddr >= image_base)
        .filter_map(|s| {
            let kind = kind_code(s.kind);
            let name_short = s.demangled.as_deref().unwrap_or(&s.mangled);
            Some((
                cstr(&s.mangled),
                cstr(name_short),
                u32::try_from(s.vaddr - image_base).ok()?,
                s.size,
                kind,
                u8::from(s.exported),
            ))
        })
        .collect();
    rows.sort_by(|a, b| a.0.cmp(&b.0));
    rows.dedup_by(|a, b| a.0 == b.0);

    let header = symbol_header(db, &ident, &upper, image_base, guid, age, timestamp);
    let c = symbol_source(&ident, &upper, guid, &rows);

    std::fs::write(&h_path, header).with_context(|| format!("writing {}", h_path.display()))?;
    std::fs::write(&c_path, c).with_context(|| format!("writing {}", c_path.display()))?;
    println!(
        "wrote {} symbols → {}/{}_syms.[ch]",
        rows.len(),
        out_dir.display(),
        name
    );
    Ok(())
}

fn symbol_header(
    db: &Database,
    ident: &str,
    upper: &str,
    image_base: u64,
    guid: &str,
    age: u32,
    timestamp: u32,
) -> String {
    format!(
        "/*\n\
         * {ident}_syms.h: generated by windissect emit-syms. DO NOT EDIT.\n\
         * Ground-truth symbol table for {dll}, anchored to PDB GUID {guid}.\n\
         * RVA = vaddr - image_base. Use only for the exact binary version above.\n\
         */\n\
         \n\
         #pragma once\n\
         \n\
         #ifndef {upper}_SYMS_H\n\
         #define {upper}_SYMS_H\n\
         \n\
         #include <stdint.h>\n\
         #include <stddef.h>\n\
         #include <stdbool.h>\n\
         \n\
         #if defined(__STDC_VERSION__) && __STDC_VERSION__ < 201710L\n\
         #error \"Windissect C output requires C17 or newer\"\n\
         #endif\n\
         #ifndef __cplusplus\n\
         #define {upper}_SYMS_C_STANDARD __STDC_VERSION__\n\
         #endif\n\
         \n\
         #ifdef __cplusplus\n\
         #if __cplusplus >= 202002L\n\
         #define WINDISSECT_C20_PROFILE 1\n\
         #else\n\
         #define WINDISSECT_C20_PROFILE 0\n\
         #endif\n\
         extern \"C\" {{\n\
         #else\n\
         #define WINDISSECT_C20_PROFILE 0\n\
         #endif\n\
         \n\
         #define {upper}_SYMS_PDB_GUID \"{guid}\"\n\
         #define {upper}_SYMS_PDB_AGE {age}U\n\
         #define {upper}_SYMS_PE_TIMESTAMP {timestamp}U\n\
         #define {upper}_SYMS_IMAGE_BASE 0x{base:X}ULL\n\
         \n\
         typedef enum {upper}SymKind {{\n\
             {upper}_KIND_CTOR = 0,\n\
             {upper}_KIND_DTOR, {upper}_KIND_REFCOUNT, {upper}_KIND_ACCESSOR,\n\
             {upper}_KIND_THUNK, {upper}_KIND_METHOD, {upper}_KIND_CFUNC,\n\
             {upper}_KIND_OPERATOR, {upper}_KIND_DATA, {upper}_KIND_UNKNOWN\n\
         }} {upper}SymKind;\n\
         \n\
         typedef struct {upper}SymEntry {{\n\
             const char* mangled;  // version-stable identity key\n\
             const char* name;     // demangled human-readable name\n\
             uint32_t rva;         // relative to {dll} image base\n\
             uint32_t size;        // function byte size\n\
             uint8_t kind;         // symbol kind\n\
             uint8_t exported;     // 1 = resolvable via GetProcAddress\n\
         }} {upper}SymEntry;\n\
         \n\
         extern const {upper}SymEntry g_{ident}_syms[];\n\
         extern const size_t g_{ident}_sym_count;\n\
         \n\
         const {upper}SymEntry* {ident}_sym_lookup(const char* mangled);\n\
         \n\
         #ifdef __cplusplus\n\
         }}\n\
         #endif\n\
         \n\
         #endif // {upper}_SYMS_H\n",
        ident = ident,
        upper = upper,
        dll = db.binary.file,
        guid = guid,
        age = age,
        timestamp = timestamp,
        base = image_base,
    )
}

fn symbol_source(
    ident: &str,
    upper: &str,
    guid: &str,
    rows: &[(String, String, u32, u32, u8, u8)],
) -> String {
    let mut source = format!(
        "/*\n\
         * {ident}_syms.c: generated by windissect emit-syms. DO NOT EDIT.\n\
         * {count} symbols. Sorted by mangled name; binary search lookup.\n\
         * pdb_guid: {guid}\n\
         */\n\
         \n\
         #include \"{ident}_syms.h\"\n\
         #include <string.h>\n\
         \n\
         const {upper}SymEntry g_{ident}_syms[] = {{\n",
        ident = ident,
        upper = upper,
        count = rows.len(),
        guid = guid,
    );

    for (mangled, demangled, rva, size, kind, exported) in rows {
        let _ = writeln!(
            source,
            "    {{ \"{mangled}\", \"{demangled}\", 0x{rva:X}, {size}, {kind}, {exported} }},"
        );
    }

    let _ = write!(
        source,
        "}};\n\
         \n\
         const size_t g_{ident}_sym_count = sizeof(g_{ident}_syms) / sizeof(g_{ident}_syms[0]);\n\
         \n\
         const {upper}SymEntry* {ident}_sym_lookup(const char* mangled) {{\n\
         \x20   size_t lo = 0, hi = g_{ident}_sym_count;\n\
         \x20   while (lo < hi) {{\n\
         \x20       size_t mid = lo + (hi - lo) / 2;\n\
         \x20       int cmp = strcmp(mangled, g_{ident}_syms[mid].mangled);\n\
         \x20       if (cmp == 0) return &g_{ident}_syms[mid];\n\
         \x20       if (cmp < 0) hi = mid; else lo = mid + 1;\n\
         \x20   }}\n\
         \x20   return NULL;\n\
         }}\n",
    );

    source
}

fn c_ident(s: &str) -> String {
    let mut out: String = s
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '_' {
                c
            } else {
                '_'
            }
        })
        .collect();
    if out.is_empty() {
        out.push_str("symbols");
    }
    if out.as_bytes()[0].is_ascii_digit() {
        out.insert(0, '_');
    }
    out
}

const fn kind_code(k: Kind) -> u8 {
    match k {
        Kind::Ctor => 0,
        Kind::Dtor => 1,
        Kind::Refcount => 2,
        Kind::Accessor => 3,
        Kind::Thunk => 4,
        Kind::Method => 5,
        Kind::CFunc => 6,
        Kind::Operator => 7,
        Kind::Data => 8,
        Kind::Unknown => 9,
    }
}

/// Escape a string for a C string literal.
fn cstr(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for ch in s.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            _ => out.push(ch),
        }
    }
    out
}
